#!/system/bin/sh
# Mihomo TProxy runtime control (generated by the app, safe to edit)
DIR=/data/adb/mihomo_tproxy
BIN=$DIR/bin/mihomo
CFG=$DIR/data/config.yaml
LOGF=$DIR/logs/core.log
PIDF=$DIR/run/core.pid

is_running() {
  [ -f "$PIDF" ] || return 1
  P=$(cat "$PIDF" 2>/dev/null)
  [ -n "$P" ] || return 1
  kill -0 "$P" 2>/dev/null || return 1
  # PID files survive reboots and PIDs get reused: make sure it is really mihomo
  tr '\0' ' ' < /proc/$P/cmdline 2>/dev/null | grep -q mihomo || return 1
  return 0
}

cleanup_rules() {
  while ip rule del pref 9000 2>/dev/null; do :; done
  while ip rule del pref 9001 2>/dev/null; do :; done
  while ip rule del pref 9010 2>/dev/null; do :; done
  ip route flush table 2022 2>/dev/null
  ip link set mihomo0 down 2>/dev/null
  ip link del mihomo0 2>/dev/null
  return 0
}

# The tunnel only carries IPv4; Google Play prefers IPv6 and would stall otherwise.
disable_ipv6_on_ifaces() {
  for i in $(ls /sys/class/net 2>/dev/null); do
    case "$i" in
      lo|mihomo0|tun*|docker*|veth*) continue ;;
    esac
    f="/proc/sys/net/ipv6/conf/$i/disable_ipv6"
    [ -w "$f" ] && echo 1 > "$f" 2>/dev/null
  done
}

start() {
  if is_running; then echo "already running"; return 0; fi
  disable_ipv6_on_ifaces
  rm -f "$PIDF"
  cleanup_rules
  mkdir -p $DIR/run $DIR/logs $DIR/data
  if [ -f "$LOGF" ]; then mv -f "$LOGF" "$LOGF.old"; fi
  cd $DIR/data || return 1
  nohup $BIN -d $DIR/data -f $CFG >> $LOGF 2>&1 &
  echo $! > $PIDF
  i=0
  while [ $i -lt 80 ]; do
    if grep -q "RESTful API listening" $LOGF 2>/dev/null; then echo started; return 0; fi
    if ! kill -0 $(cat $PIDF 2>/dev/null) 2>/dev/null; then echo "exit early"; return 1; fi
    sleep 0.1
    i=$((i+1))
  done
  echo started
  return 0
}

stop() {
  if [ -f "$PIDF" ]; then
    P=$(cat $PIDF 2>/dev/null)
    kill -TERM $P 2>/dev/null
    i=0
    while kill -0 $P 2>/dev/null && [ $i -lt 40 ]; do sleep 0.1; i=$((i+1)); done
    kill -9 $P 2>/dev/null
    rm -f $PIDF
  fi
  pkill -TERM -f "$BIN" 2>/dev/null
  sleep 0.3
  cleanup_rules
  echo stopped
}

case "$1" in
  start) start ;;
  stop) stop ;;
  restart) stop; sleep 0.5; start ;;
  status) if is_running; then echo running; else echo stopped; fi ;;
  cleanup) cleanup_rules; echo cleaned ;;
  *) echo "usage: $0 start|stop|restart|status|cleanup" ;;
esac
